mapper.select:
SELECT id, template_id, template_name, biz_type, biz_id, biz_name,
       applicant, status, current_node_seq, remark,
       organization_id, create_user, update_user, create_time, update_time
FROM crm_approval_instance
WHERE applicant = #{applicant}
  AND organization_id = #{organizationId}

    AND biz_type = #{bizType}


    AND status = #{status}


    AND (biz_name LIKE CONCAT('%', #{keyword}, '%')
         OR template_name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY create_time DESC

SELECT i.id, i.template_id, i.template_name, i.biz_type, i.biz_id, i.biz_name, i.applicant, i.status, i.current_node_seq, i.remark, i.organization_id, i.create_user, i.update_user, i.create_time, i.update_time FROM crm_approval_instance i INNER JOIN crm_approval_node_record r ON i.id = r.instance_id WHERE r.approver_id = #{approverId} AND r.status = 'pending' AND i.status = 'pending' AND i.organization_id = #{organizationId}
AND i.biz_type = #{bizType}
AND (i.biz_name LIKE CONCAT('%', #{keyword}, '%') OR i.template_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY i.create_time DESC

SELECT id, template_id, template_name, biz_type, biz_id, biz_name,
       applicant, status, current_node_seq, remark,
       organization_id, create_user, update_user, create_time, update_time
FROM crm_approval_instance
WHERE organization_id = #{organizationId}

    AND biz_type = #{bizType}


    AND status = #{status}


    AND (biz_name LIKE CONCAT('%', #{keyword}, '%')
         OR template_name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY create_time DESC
